// Conceptual windowed aggregation in C#
public class WindowedCounter
{
    private readonly Dictionary<Window, long> _counts = new();

    public void Process(ClickEvent evt, TimeSpan windowSize)
    {
        var windowStart = new DateTime(
            evt.Timestamp.Year,
            evt.Timestamp.Month,
            evt.Timestamp.Day,
            evt.Timestamp.Hour,
            evt.Timestamp.Minute,
            0);

        var window = new Window(windowStart, windowStart.Add(windowSize));
        _counts[window] = _counts.GetValueOrDefault(window) + 1;
    }

    public IReadOnlyDictionary<Window, long> GetResults() => _counts;
}

public record Window(DateTime Start, DateTime End);
